const CONFIG = {

  // ── Consumo e contrato (da fatura EDP de jul/ago 2026) ──────
  consumo_kwh:  614,    // kWh faturados na última fatura
  dias:          31,    // dias do período de faturação
  potencia_kva:  6.90,  // kVA contratados (filtra tarifários do CSV)
  ciclo: "Simples",     // "Simples" | "Bi-horário" | "Tri-horário"

  // ── Tarifário FIXO ATUAL (procurado no CSV por nome parcial) ──
  // Deixa vazio para não mostrar a comparação com o atual.
  atual_nome: "EDP | Eletricidade · Digital · Campanha -20%",

  // ── Tarifário FIXO ──────────────────────────────────────────────
  // null  → escolhe automaticamente o mais barato do CSV do Tiago Felícia
  // {...} → usa estes valores directamente (ignora o CSV)
  fixo_manual: null,

  // ── Filtros para escolha automática do melhor fixo ──────────────
  // Usa string vazia "" para ignorar esse filtro.
  filtros: {
    segmento:  "Residencial",     // "Residencial" | "Empresarial" | ""
    faturacao: "eletrónica",      // palavra parcial (ex: "eletrónica", "papel")
    pagamento: "Débito",          // palavra parcial (ex: "Débito", "Multibanco")
  },

  // ── Tarifário INDEXADO (G9 | Smart Dynamic SPOT 8!) ─────────────
  // Fórmula oficial (calculos.py Tiago Felícia + Indexados.csv):
  //   preço_kwh = OMIE_€/kWh * G9_FA * perdas + G9_CGS + G9_AC + TAR_en
  // G9_FA = 1.02 (Constantes.csv G9_K1);  G9_CGS+G9_AC = 0.0155
  // Potência 6.9 kVA = 0.6242 €/dia (Indexados.csv; tar_pot incluída → preço final)
  // TSE já incluído (financiamento_tse_incluido=True)
  indexado: {
    nome:         "G9 | Smart Dynamic SPOT 8!",
    g9_fa:        1.02,
    margem_kwh:   0.0155,
    tse_incluido: true,
    potencia_dia: 0.6242,  // 6.9 kVA
  },

  // ── Referência: EDP Indexada Média (mesmo comercializador) ──────
  // OMIE/1000 * EDP_M_Perdas(1.164) * EDP_M_K1(1.1) + EDP_M_K2(0.0185)
  edp_media: {
    nome:         "EDP | Eletricidade Indexada Média",
    k_perdas:     1.164,
    k1:           1.1,
    margem_kwh:   0.0185,
    potencia_dia: 0.4607,  // 6.9 kVA (Indexados.csv)
  },

  // ── Tarifas reguladas ERSE 2026 (Constantes.csv Tiago Felícia) ──
  tar: {
    energia_kwh:  0.0607,    // €/kWh — tarifa simples BTN
    potencia_dia: 0.3436,    // €/dia — para 6.9 kVA
  },

  // Dias de histórico a considerar para a média OMIE e perdas
  dias_omie: 30,
};

// ╔══════════════════════════════════════════════════════════════════╗
// ║          NÃO É NECESSÁRIO EDITAR ABAIXO DAQUI                   ║
// ╚══════════════════════════════════════════════════════════════════╝

// Financiamento TSE (Constantes.csv)
const TSE = 0.0020666;  // €/kWh

const r4 = (v) => Math.round(v * 10000) / 10000;
const r2 = (v) => Math.round(v * 100) / 100;

const norm = (s) => (s || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim();

function parseCSVLine(linha) {
  const cols = [];
  let cur = '';
  let inQ = false;
  for (const ch of linha) {
    if (ch === '"') { inQ = !inQ; }
    else if (ch === ',' && !inQ) { cols.push(cur.trim()); cur = ''; }
    else { cur += ch; }
  }
  cols.push(cur.trim());
  return cols;
}

const parseBool = (v) => {
  const s = (v || '').toLowerCase().trim();
  return s === 'true' || s === 'sim' || s === '1';
};
const parseNum = (v) => parseFloat((v || '0').replace(',', '.')) || 0;

// ── OMIE + Perdas a partir do CSV único (substitui 31 requests) ──
function obterOMIEePerdas(csvTexto) {
  const linhas = csvTexto.split('\n').map(l => l.trim()).filter(Boolean);
  if (linhas.length < 2) throw new Error('CSV OMIE vazio ou inválido');

  const cab = parseCSVLine(linhas[0]).map(c => c.replace(/^\uFEFF/, '').replace(/"/g, '').trim().toLowerCase());
  const idx = {};
  cab.forEach((c, i) => { idx[c] = i; });
  const iData = idx['data'];
  const iOMIE = idx['omie'];
  const iPerd = idx['perdas'];
  if (iData === undefined || iOMIE === undefined || iPerd === undefined) {
    throw new Error('Colunas do CSV OMIE não encontradas: ' + JSON.stringify(cab));
  }

  const hoje = new Date();
  const limite = CONFIG.dias_omie;
  const valoresOMIE = [];
  const valoresPerdas = [];

  for (let i = 1; i < linhas.length; i++) {
    const cols = parseCSVLine(linhas[i]);
    if (cols.length <= Math.max(iData, iOMIE, iPerd)) continue;

    // Data no formato MM/DD/YYYY
    const ds = cols[iData].trim();
    const m = ds.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
    if (!m) continue;
    const d = new Date(+m[3], +m[1] - 1, +m[2]);
    const diff = Math.floor((hoje - d) / 86400000);
    if (diff < 0 || diff > limite) continue;

    const rawOmie = cols[iOMIE].trim();
    const rawPerd = cols[iPerd].trim();
    if (rawOmie !== '' && !isNaN(parseFloat(rawOmie))) valoresOMIE.push(parseFloat(rawOmie));
    if (rawPerd !== '' && !isNaN(parseFloat(rawPerd))) valoresPerdas.push(parseFloat(rawPerd));
  }

  const media = (arr) => arr.reduce((a, b) => a + b, 0) / arr.length;
  const mediaOMIE = valoresOMIE.length ? media(valoresOMIE) : 60.0;
  const mediaPerdas = valoresPerdas.length ? media(valoresPerdas) : 1.1488;

  return { media_omie_mwh: mediaOMIE, perdas: mediaPerdas, num_omie: valoresOMIE.length };
}

// ── Melhor fixo a partir do CSV de tarifários ──────────────────
function obterTarifarios(csvTexto) {
  const linhas = csvTexto.split('\n').map(l => l.trim()).filter(Boolean);
  if (linhas.length < 2) throw new Error('CSV vazio ou inválido');

  const cab = parseCSVLine(linhas[0]).map(c => c.replace(/"/g, '').trim().toLowerCase());
  const col = (nome) => cab.findIndex(c => c.includes(nome.toLowerCase()));

  const C = {
    comercializador: col('comercializador'),
    nome:            col('nome'),
    tipo:            col('tipo'),
    ciclo:           col('opcao_horaria'),
    potKva:          col('potencia_kva'),
    energia:         col('preco_energia_simples'),
    potDia:          col('preco_potencia_dia'),
    tarEnIncl:       col('tar_incluida_energia'),
    tarPotIncl:      col('tar_incluida_potencia'),
    tseIncl:         col('financiamento_tse'),
    segmento:        col('segmento'),
    faturacao:       col('faturacao'),
    pagamento:       col('pagamento'),
    descFatura:      col('desconto_fatura'),
    site:            col('site_adesao'),
  };

  const cicloChave = norm(CONFIG.ciclo).split('-')[0].split(' ')[0];
  const fixos = [];
  let meuAtual = null;

  for (let i = 1; i < linhas.length; i++) {
    const cols = parseCSVLine(linhas[i]);
    if (cols.length < 10) continue;

    const tipo    = (cols[C.tipo]    || '').replace(/"/g, '').trim();
    const ciclo   = norm(cols[C.ciclo]   || '');
    const potKva  = parseNum(cols[C.potKva]);
    const segmento  = norm(cols[C.segmento]  || '');
    const faturacao = norm(cols[C.faturacao] || '');
    const pagamento = norm(cols[C.pagamento] || '');
    const nomeTar   = (cols[C.nome]  || '').replace(/"/g, '').trim();

    if (norm(tipo) !== 'fixo') continue;
    if (Math.abs(potKva - CONFIG.potencia_kva) > 0.1) continue;
    if (!ciclo.includes(cicloChave)) continue;

    const f = CONFIG.filtros;
    if (f.segmento === 'Residencial' && !segmento.includes('domestico')) continue;
    if (f.segmento === 'Empresarial' && !segmento.includes('nao domestico') && !segmento.includes('nao-domestico')) continue;
    if (f.faturacao && !faturacao.includes(norm(f.faturacao))) continue;
    if (f.pagamento && !pagamento.includes(norm(f.pagamento))) continue;

    const energiaBruta = parseNum(cols[C.energia]);
    const potDiaBruta  = parseNum(cols[C.potDia]);
    if (energiaBruta <= 0 || potDiaBruta <= 0) continue;

    const tarEnIncl  = parseBool(cols[C.tarEnIncl]);
    const tarPotIncl = parseBool(cols[C.tarPotIncl]);
    const tseIncl    = parseBool(cols[C.tseIncl]);

    const energiaComercial = tarEnIncl ? energiaBruta - CONFIG.tar.energia_kwh : energiaBruta;
    const potComercial     = tarPotIncl ? potDiaBruta - CONFIG.tar.potencia_dia : potDiaBruta;
    const energiaFinal = energiaComercial + CONFIG.tar.energia_kwh + (tseIncl ? 0 : TSE);
    const potFinal     = potComercial + CONFIG.tar.potencia_dia;

    const descFatura = parseNum(cols[C.descFatura] || '0');
    const descTotal  = descFatura * (CONFIG.dias / 30);
    const custoTotal = energiaFinal * CONFIG.consumo_kwh + potFinal * CONFIG.dias - descTotal;

    fixos.push({
      comercializador: (cols[C.comercializador] || '').replace(/"/g, '').trim(),
      nome:            nomeTar,
      site:            (cols[C.site] || '').replace(/"/g, '').trim(),
      energia_kwh:     r4(energiaFinal),
      potencia_dia:    r4(potFinal),
      custo_estimado:  r2(custoTotal),
    });

    // Tarifário atual
    if (CONFIG.atual_nome && nomeTar.toLowerCase().includes(CONFIG.atual_nome.toLowerCase())) {
      if (!meuAtual || custoTotal < meuAtual.custo_estimado) {
        meuAtual = { nome: nomeTar, custo_estimado: r2(custoTotal), energia_kwh: r4(energiaFinal), potencia_dia: r4(potFinal) };
      }
    }
  }

  fixos.sort((a, b) => a.custo_estimado - b.custo_estimado);
  fixos.sort((a, b) => a.custo_estimado - b.custo_estimado);
  const melhorFixoL = fixos[0];
  let posPromo = null;
  if (melhorFixoL) {
    const base = (melhorFixoL.nome.split('(')[0] || melhorFixoL.nome).trim().toLowerCase();
    for (const f of fixos) {
      if (f.nome === melhorFixoL.nome) continue;
      const fb = (f.nome.split('(')[0] || f.nome).trim().toLowerCase();
      if (fb && fb === base && f.nome.toLowerCase().includes('depois')) {
        posPromo = f;
        break;
      }
    }
  }
  return { melhor: fixos[0], todos: fixos, atual: meuAtual, posPromo };
}

// ── Main ────────────────────────────────────────────────────────
try {
  // Dados dos nós anteriores
  const omieTexto  = $('HTTP Request CSV OMIE+Perdas').first().json.data;
  const fixosTexto = $('HTTP Request CSV Tarifários').first().json.data;

  const { media_omie_mwh, perdas, num_omie } = obterOMIEePerdas(omieTexto);
  const { melhor: melhorFixo, todos, atual: meuAtual, posPromo } = obterTarifarios(fixosTexto);

  const mediaOmie_kWh = media_omie_mwh / 1000;

  // ── Indexado G9 ──
  const idx = CONFIG.indexado;
  const precoKwhIndexado = (
    mediaOmie_kWh * idx.g9_fa * perdas
    + idx.margem_kwh
    + CONFIG.tar.energia_kwh
    + (idx.tse_incluido ? 0 : TSE)
  );
  const custoIndexado = CONFIG.consumo_kwh * precoKwhIndexado + CONFIG.dias * idx.potencia_dia;

  // ── EDP Indexada Média (referência) ──
  const edp = CONFIG.edp_media;
  const precoKwhEDP = mediaOmie_kWh * edp.k_perdas * edp.k1 + edp.margem_kwh + CONFIG.tar.energia_kwh;
  const custoEDP = CONFIG.consumo_kwh * precoKwhEDP + CONFIG.dias * edp.potencia_dia;

  // ── Break-even (OMIE em que fixo = indexado) ──
  const custoFixo = melhorFixo ? melhorFixo.custo_estimado : 0;
  const breakeven_kWh = (
    (custoFixo - CONFIG.dias * idx.potencia_dia) / CONFIG.consumo_kwh
    - idx.margem_kwh
    - CONFIG.tar.energia_kwh
    - (idx.tse_incluido ? 0 : TSE)
  ) / (idx.g9_fa * perdas);
  const breakeven_MWh = r2(breakeven_kWh * 1000);

  // ── Recomendação entre atual / melhor fixo / indexado ──
  const opcoes = [];
  if (meuAtual) opcoes.push({ tipo: 'atual', nome: meuAtual.nome, custo: meuAtual.custo_estimado });
  if (melhorFixo) opcoes.push({ tipo: 'melhor_fixo', nome: melhorFixo.nome, custo: melhorFixo.custo_estimado });
  opcoes.push({ tipo: 'indexado', nome: idx.nome, custo: r2(custoIndexado) });

  opcoes.sort((a, b) => a.custo - b.custo);
  const melhor = opcoes[0];
  const poupancaVsAtual = meuAtual ? r2(Math.abs(meuAtual.custo_estimado - melhor.custo)) : 0;
  const poupancaFixoVsIdx = melhorFixo ? r2(Math.abs(custoFixo - r2(custoIndexado))) : 0;

  let label;
  if (melhor.tipo === 'atual') label = `🏆 ATUAL é a melhor opção — poupas ${poupancaVsAtual}€ vs 2ª melhor`;
  else if (melhor.tipo === 'melhor_fixo') label = `🏆 FIXO mais barato — poupa ${poupancaFixoVsIdx}€ vs indexado`;
  else label = `🏆 INDEXADO mais barato — poupa ${poupancaFixoVsIdx}€`;

  // ── Resumo ──
  const data = new Date().toLocaleDateString('pt-PT');
  let resumo = `📊 *ANÁLISE OMIE* (${data})\n`;
  resumo += `━━━━━━━━━━━━━━━━━━━━\n\n`;
  resumo += `⚡ *MERCADO OMIE (últimos ${CONFIG.dias_omie} dias):*\n`;
  resumo += `• Média: *${r2(media_omie_mwh)} €/MWh*\n`;
  resumo += `• Perdas rede: ${perdas.toFixed(4)} | Break-even: ${breakeven_MWh} €/MWh\n\n`;

  if (meuAtual) {
    resumo += `📄 *TARIFÁRIO ATUAL:*\n• ${meuAtual.nome}\n• Custo estimado: *${meuAtual.custo_estimado}€*\n\n`;
  }

  const fonte = 'automatico (CSV Tiago Felícia)';
  resumo += `🔒 *MELHOR FIXO (${fonte}):*\n`;
  if (melhorFixo) {
    resumo += `• ${melhorFixo.nome}\n`;
    resumo += `• Energia: ${melhorFixo.energia_kwh} €/kWh | Potência: ${melhorFixo.potencia_dia} €/dia\n`;
    resumo += `• Custo estimado: *${melhorFixo.custo_estimado}€*\n`;
    if (posPromo) {
      resumo += `• ⚠️ Após promoção: ${posPromo.energia_kwh} €/kWh → *${posPromo.custo_estimado}€*\n`;
    }
    resumo += `\n`;
  } else {
    resumo += `• Nenhum tarifário encontrado\n\n`;
  }

  resumo += `📈 *INDEXADO (${idx.nome}):*\n`;
  resumo += `• Preço kWh: ${r4(precoKwhIndexado)} €/kWh | Potência: ${idx.potencia_dia} €/dia\n`;
  resumo += `• Custo estimado: *${r2(custoIndexado)}€*\n\n`;
  resumo += `📈 *REF. EDP Indexada Média:* ${r2(custoEDP)}€\n\n`;
  resumo += `━━━━━━━━━━━━━━━━━━━━\n`;
  resumo += `💡 *${label}*\n`;
  resumo += `   Recomendação: *${melhor.nome}*`;

  return [{
    json: {
      data_analise:              data,
      media_omie_eur_mwh:        r2(media_omie_mwh),
      perdas_rede:               r4(perdas),
      breakeven_eur_mwh:         breakeven_MWh,
      omie_acima_breakeven:      media_omie_mwh > breakeven_MWh,
      // Atual
      tarifario_atual_nome:      meuAtual ? meuAtual.nome : '',
      custo_atual_eur:           meuAtual ? meuAtual.custo_estimado : 0,
      poupanca_vs_atual_eur:     poupancaVsAtual,
      // Melhor fixo
      melhor_fixo_nome:          melhorFixo ? melhorFixo.nome : '',
      melhor_fixo_comercializador: melhorFixo ? melhorFixo.comercializador : '',
      melhor_fixo_site:          melhorFixo ? melhorFixo.site : '',
      melhor_fixo_fonte:         fonte,
      melhor_fixo_energia_kwh:   melhorFixo ? melhorFixo.energia_kwh : 0,
      melhor_fixo_potencia_dia:  melhorFixo ? melhorFixo.potencia_dia : 0,
      custo_melhor_fixo_eur:     custoFixo,
      melhor_fixo_pos_promo_custo_eur: posPromo ? posPromo.custo_estimado : null,
      melhor_fixo_pos_promo_energia_kwh: posPromo ? posPromo.energia_kwh : null,
      // Indexado
      indexado_nome:             idx.nome,
      indexado_preco_kwh:        r4(precoKwhIndexado),
      indexado_potencia_dia:     idx.potencia_dia,
      custo_indexado_eur:        r2(custoIndexado),
      indexado_edp_media_custo_eur: r2(custoEDP),
      // Comparação
      poupanca_eur:              poupancaFixoVsIdx,
      recomendacao:              melhor.nome,
      fixo_mais_barato:          melhorFixo ? custoFixo <= r2(custoIndexado) : null,
      num_omie:                  num_omie,
      consumo_kwh:               CONFIG.consumo_kwh,
      dias_faturacao:            CONFIG.dias,
      resumo,
    }
  }];
} catch (e) {
  return [{ json: { erro: e.message } }];
}
